/**
 * search-inline.ts — inline dropdown search over the Pagefind full-body index.
 * No modal, no backdrop blur: results drop down right under the input. Keyboard ↑ ↓ Enter Esc, ⌘K focus.
 * Wire on any element containing `[data-search-input]` + `[data-search-results]`.
 */
import { loadPagefind } from '../lib/pagefind-client';
import { DOMAIN_LABELS, isDomain } from '../lib/types';

/** Warm Pagefind after idle so first keystroke doesn't hitch the main thread. */
function preloadPagefind(): void {
  const run = () => void loadPagefind(18).catch(() => {});
  if ('requestIdleCallback' in window) {
    requestIdleCallback(run, { timeout: 2500 });
  } else {
    setTimeout(run, 800);
  }
}

const domainLabel = (raw?: string) => (raw && isDomain(raw) ? DOMAIN_LABELS[raw] : (raw ?? ''));
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let cmdKBound = false;

export function initInlineSearch(root: HTMLElement): void {
  const input = root.querySelector<HTMLInputElement>('[data-search-input]');
  const list = root.querySelector<HTMLElement>('[data-search-results]');
  if (!input || !list) return;

  let active = -1;
  let rows: { url: string; title: string; domain: string; excerpt: string }[] = [];

  const show = (v: boolean) => {
    list.hidden = !v;
    root.classList.toggle('open', v);
  };

  const render = () => {
    list.innerHTML = '';
    if (!input.value.trim()) return show(false);
    if (!rows.length) {
      list.innerHTML = '<p class="kb-ac-empty">No notes found.</p>';
      return show(true);
    }
    rows.forEach((r, i) => {
      const a = document.createElement('a');
      a.href = r.url;
      a.className = 'kb-ac-row' + (i === active ? ' on' : '');
      a.innerHTML =
        `<span class="kb-ac-title">${esc(r.title)}</span>` +
        (r.domain ? `<span class="kb-ac-domain">${esc(r.domain)}</span>` : '') +
        (r.excerpt ? `<span class="kb-ac-ex">${esc(r.excerpt)}</span>` : '');
      a.addEventListener('mousedown', (e) => {
        e.preventDefault();
        window.location.href = r.url;
      });
      list.append(a);
    });
    show(true);
  };

  let timer: ReturnType<typeof setTimeout> | undefined;
  const run = async (q: string) => {
    if (!q.trim()) {
      rows = [];
      return render();
    }
    try {
      const api = await loadPagefind(18);
      const { results } = await api.search(q.trim());
      rows = await Promise.all(
        results.slice(0, 8).map(async (h) => {
          const d = await h.data();
          return {
            url: d.url,
            title: d.meta.title ?? d.url.split('/').filter(Boolean).pop() ?? 'Note',
            domain: domainLabel(d.meta.domain),
            excerpt: d.excerpt?.trim() || '',
          };
        }),
      );
      active = -1;
      render();
    } catch {
      list.innerHTML = '<p class="kb-ac-empty">Search index loading…</p>';
      show(true);
    }
  };

  input.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(() => void run(input.value), 110);
  });
  input.addEventListener('focus', () => {
    if (input.value.trim()) render();
  });
  input.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      active = Math.min(active + 1, rows.length - 1);
      render();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      active = Math.max(active - 1, 0);
      render();
    } else if (e.key === 'Enter') {
      const pick = rows[active] ?? rows[0];
      if (pick) {
        e.preventDefault();
        window.location.href = pick.url;
      }
    } else if (e.key === 'Escape') {
      show(false);
      input.blur();
    }
  });

  document.addEventListener('click', (e) => {
    if (!root.contains(e.target as Node)) show(false);
  });

  if (!cmdKBound) {
    cmdKBound = true;
    preloadPagefind();
    document.addEventListener('keydown', (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        document.querySelector<HTMLInputElement>('.kb-chrome [data-search-input]')?.focus();
      }
    });
  }
}

---
/**
 * map.astro — the Map: the full VAULT GRAPH on top (every note + link), then the six domains listed
 * below as a plain index. The per-domain page lists are computed from the live collection
 * (doctrine-first, knowledge pages only), so they stay current as the vault grows.
 */
import { getCollection } from 'astro:content';
import Base from '../layouts/Base.astro';
import Constellation from '../components/Constellation.astro';
import { buildGraph, type NoteInput } from '../lib/graph';
import { deriveTitle } from '../lib/note';
import { slugToUrl } from '../lib/slug';
import { DOMAINS, DOMAIN_LABELS } from '../lib/types';
import { DOMAIN_ICONS } from '../lib/icons';
import Icon from '../components/Icon.astro';

const PER_SECTION = 8;

// One concrete line per domain: a real idea from inside it, useful to the reader — never a
// restatement of the category (the heading and the list already say what it is). Front-facing:
// 02 - System/Writing Standards.md → Specific Beats Generic, Details Not Conclusions (no A-is-A).
const DOMAIN_BLURB: Record<string, string> = {
  learning: 'Retrieval and spacing help you remember what you read.',
  agentic: 'When agents write the code, your job is to direct them well.',
  language: 'Chinese characters are built from a few hundred reusable parts.',
  focus: 'Attention is limited, and a feed decides where yours goes.',
  mind: 'Decisions improve when you red-team your own reasoning first.',
  gen: 'Wealth is owning part of something that grows without more of your time.',
};

// Doctrine-first ordering: hubs and condensed pages lead, then syntheses, then supporting types,
// with link degree as the tiebreaker. New pages slot in by type, so it stays sensible as it grows.
const TYPE_RANK: Record<string, number> = {
  hub: 100,
  synthesis: 80,
  system: 70,
  model: 60,
  dimension: 60,
  pillar: 45,
  primer: 40,
  workflow: 35,
  technique: 25,
  concept: 20,
  book: 15,
};

const notes = await getCollection('notes');
const input: NoteInput[] = notes.map((n) => ({
  slug: n.id,
  title: deriveTitle(n.data, n.id, n.body),
  type: typeof n.data.type === 'string' ? n.data.type : '',
  body: n.body ?? '',
}));
const full = buildGraph(input);

const degree = new Map<string, number>();
for (const e of full.edges) {
  degree.set(e.source, (degree.get(e.source) ?? 0) + 1);
  degree.set(e.target, (degree.get(e.target) ?? 0) + 1);
}
const score = (n: (typeof full.nodes)[number]) => {
  const tier = Math.max(TYPE_RANK[n.type] ?? 12, /,\s*Condensed$/i.test(n.title) ? 90 : 0);
  return tier * 1000 + (degree.get(n.slug) ?? 0);
};

const byDomain = new Map<string, (typeof full.nodes)[number][]>();
for (const n of full.nodes) {
  if (!n.slug.startsWith('wiki/')) continue; // knowledge pages only — exclude journal, index, about
  (byDomain.get(n.domain) ?? byDomain.set(n.domain, []).get(n.domain)!).push(n);
}

const sections = DOMAINS.map((d) => {
  const all = (byDomain.get(d) ?? []).sort((a, b) => score(b) - score(a) || a.title.localeCompare(b.title));
  return {
    domain: d,
    label: DOMAIN_LABELS[d],
    icon: DOMAIN_ICONS[d],
    items: all.slice(0, PER_SECTION),
  };
});
